INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (13, 38, 'theory', 'Quiz: data and types');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 38, 0, 'What does the @dataclass decorator generate automatically?', '["Only __str__", "A constructor, __repr__, and comparison by fields", "A database", "Properties for all fields"]', 1, 'That is the main payoff: instead of twenty lines of boilerplate, just a list of fields.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 38, 1, 'What is the right way to set an empty list as a default in a dataclass?', '["items: list = []", "items: list = field(default_factory=list)", "items = list", "items: list = None"]', 1, 'Mutable defaults are forbidden; default_factory creates a new list for each instance.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 38, 2, 'What happens on Color(9) if the Enum has no member with value 9?', '["None is returned", "ValueError: 9 is not a valid Color", "A new member is created", "The first member is returned"]', 1, 'An enumeration protects you from values that don''t exist.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 38, 3, 'Does Python check type hints at run time?', '["Yes, always", "No: people, editors, and analyzers (mypy) read them", "Only for int", "Only in dataclasses"]', 1, 'add(''a'', ''b'') with an int hint happily returns ''ab''; it is a static analyzer that checks this.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 38, 4, 'a = [[1, 2], [3]]; b = copy.copy(a); a[0].append(9). What is in b[0]?', '["[1, 2]", "[1, 2, 9]", "[9]", "An error"]', 1, 'copy.copy makes a shallow copy: the nested lists stay shared. For independence you need deepcopy.');
